var t=`0174-gnocchi-di-patate`;var n=`world-0174`;var o=`IT`;var a=`southern-europe`;var s=4;var g=66;var r={en:`Gnocchi di Patate`,ua:`Картопляні ньокі`};var l={en:`A classic dish from Italy, featuring potato, chicken egg, sage, parmigiano reggiano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: картопля, куряче яйце, шавлія, парміджано реджано. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`potato`,900,`g`],[`water`,1250,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`all-purpose-flour`,230,`g`],[`chicken-egg`,1,`pcs`],[`table-salt`,4,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:16,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 5 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 5 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:5,i:[[`water`,1400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,70,`g`],[`sage`,15,`g`],[`parmigiano-reggiano`,75,`g`]]}];var u={slug:t,id:n,country:`IT`,region:a,servings:4,minutes:66,title:r,text:l,steps:d};export{o as country,u as default,n as id,g as minutes,a as region,s as servings,t as slug,d as steps,l as text,r as title};